   120	    const taskReportID = optimisticTaskReport.reportID;
   121	    let assigneeChatReportOnyxData;
   122	
   123	    // Parent ReportAction indicating that a task has been created
   124	    const optimisticTaskCreatedAction = ReportUtils.buildOptimisticCreatedReportAction(currentUserEmail);
   125	    const optimisticAddCommentReport = ReportUtils.buildOptimisticTaskCommentReportAction(taskReportID, title, assigneeAccountID, `task for ${title}`, parentReportID);
   126	    optimisticTaskReport.parentReportActionID = optimisticAddCommentReport.reportAction.reportActionID;
   127	
   128	    const currentTime = DateUtils.getDBTimeWithSkew();
   129	    const lastCommentText = ReportUtils.formatReportLastMessageText(ReportActionsUtils.getReportActionText(optimisticAddCommentReport.reportAction));
   130	    const parentReport = ReportUtils.getReport(parentReportID);
   131	    const optimisticParentReport = {
   132	        lastVisibleActionCreated: optimisticAddCommentReport.reportAction.created,
   133	        lastMessageText: lastCommentText,
   134	        lastActorAccountID: currentUserAccountID,
   135	        lastReadTime: currentTime,
