   140	    // We're only setting onyx data for the task report here because it's possible for the parent report to not exist yet (if you're assigning a task to someone you haven't chatted with before)
   141	    // So we don't want to set the parent report data until we've successfully created that chat report
   142	    // FOR TASK REPORT
   143	    const optimisticData: OnyxUpdate[] = [
