   246	    // If needed, update optimistic data for parent report action of the parent report.
   247	    const optimisticParentReportData = ReportUtils.getOptimisticDataForParentReportAction(parentReportID, currentTime, CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD);
   248	    optimisticParentReportData.forEach((parentReportData) => {
