   305	function getOutstandingChildTask(taskReport: OnyxEntry<OnyxTypes.Report>) {
   306	    const parentReportActions = allReportActions?.[`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${taskReport?.parentReportID}`] ?? {};
   307	    return Object.values(parentReportActions).some((reportAction) => {
   308	        if (String(reportAction.childReportID) === String(taskReport?.reportID)) {
   309	            return false;
   310	        }
   311	
   312	        if (
   313	            reportAction.childType === CONST.REPORT.TYPE.TASK &&
   314	            reportAction?.childStateNum === CONST.REPORT.STATE_NUM.OPEN &&
   315	            reportAction?.childStatusNum === CONST.REPORT.STATUS_NUM.OPEN &&
   316	            ReportActionsUtils.getReportActionMessage(reportAction)?.isDeletedParentAction
   317	        ) {
   318	            return true;
   319	        }
   320	
   321	        return false;
   322	    });
   323	}
